/** Simple vector shapes, generated by us — never injected foreign SVG markup. */

import type { ShapeSpec } from '../../domain/types'

export function ShapeView({ shape }: { shape: ShapeSpec }) {
  const stroke = shape.stroke
  const strokeWidth = shape.strokeWidth
  const inset = strokeWidth / 2

  return (
    <svg
      className="shape-view"
      viewBox="0 0 100 100"
      preserveAspectRatio="none"
      role="img"
      aria-label={`Figur: ${shape.kind}`}
    >
      {shape.kind === 'rectangle' && (
        <rect
          x={inset}
          y={inset}
          width={100 - strokeWidth}
          height={100 - strokeWidth}
          rx={3}
          fill={shape.fill}
          stroke={stroke}
          strokeWidth={strokeWidth}
          vectorEffect="non-scaling-stroke"
        />
      )}
      {shape.kind === 'ellipse' && (
        <ellipse
          cx={50}
          cy={50}
          rx={50 - inset}
          ry={50 - inset}
          fill={shape.fill}
          stroke={stroke}
          strokeWidth={strokeWidth}
          vectorEffect="non-scaling-stroke"
        />
      )}
      {shape.kind === 'triangle' && (
        <polygon
          points={`50,${inset} ${100 - inset},${100 - inset} ${inset},${100 - inset}`}
          fill={shape.fill}
          stroke={stroke}
          strokeWidth={strokeWidth}
          vectorEffect="non-scaling-stroke"
        />
      )}
      {shape.kind === 'line' && (
        <line
          x1={inset}
          y1={50}
          x2={100 - inset}
          y2={50}
          stroke={stroke}
          strokeWidth={strokeWidth}
          vectorEffect="non-scaling-stroke"
          strokeLinecap="round"
        />
      )}
      {shape.kind === 'arrow' && (
        <g stroke={stroke} strokeWidth={strokeWidth} fill="none" vectorEffect="non-scaling-stroke">
          <line x1={inset} y1={50} x2={84} y2={50} strokeLinecap="round" />
          <polyline points={`68,26 ${100 - inset},50 68,74`} strokeLinecap="round" strokeLinejoin="round" />
        </g>
      )}
    </svg>
  )
}
